(function () {
  var A = window.App, M = window.MOCK, t = I18N.t, esc = A.esc, $ = A.$;
  var Q = ['q-webhook-sig', 'q-idempotency', 'q-ussd-timeout'], R = ['r-kalimba', 'r-sahel-sms', 'r-baobab-kyc'], P = ['pr-webhook-kit', 'pr-docs-fr', 'pr-offline-drafts'];
  var PSTAT = { active: ['open', 'landing.p.active'], seeking: ['open', 'landing.p.seeking'], idea: ['draft', 'landing.p.idea'] };

  function slug(x) { return String(x).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
  function ic(name, id) { return '<span class="icon i-' + name + '" aria-hidden="true" data-testid="' + id + '"></span>'; }
  function tags(arr, id, max) { return '<ul class="tag-list list-reset" data-testid="' + id + '-tags">' + arr.slice(0, max || 4).map(function (x) { return '<li class="tag" data-testid="' + id + '-tag-' + slug(x) + '">' + esc(x) + '</li>'; }).join('') + '</ul>'; }
  function codes(list, id) {
    var names = list.map(function (c) { return M.countryName(c); }).join(', ');
    return '<span class="lp-countries" data-testid="' + id + '-countries"><span class="visually-hidden" data-testid="' + id + '-countries-names">' + esc(names) + '</span>' + list.map(function (c) { return '<span class="country-code" aria-hidden="true" data-testid="' + id + '-country-' + c.toLowerCase() + '">' + c + '</span>'; }).join('') + '</span>';
  }
  function plain(s) { return s.replace(/\s*\(fictifs?\)\s*$/i, ''); }
  function first(s) { var m = s.match(/^.*?[.!?](\s|$)/); return m ? m[0].trim() : s; }
  function statePill(kind, id, key) { return A.statePill(kind, { testid: id, labelKey: key }); }
  function dateEl(iso, id) { return '<time datetime="' + iso + '" class="tabular-nums" data-testid="' + id + '">' + esc(M.fmtDate(iso)) + '</time>'; }

  /* Hero preview: one real chain (question -> API -> project) built from the mock data. */
  function renderPreview() {
    var q = M.byId(M.questions, 'q-webhook-sig'), r = M.byId(M.resources, q.resource), p = M.byId(M.projects, q.project), pid = 'landing-preview';
    var qc = '<a class="lp-pc lp-pc-q" href="pages/question.html?id=' + q.id + '" data-testid="' + pid + '-question">' +
      '<span class="lp-pc-top">' + statePill('accepted', pid + '-accepted') + '<span class="lp-pc-meta tabular-nums" data-testid="' + pid + '-question-votes">' + q.votes + ' ' + esc(t('landing.q.votes')) + '</span></span>' +
      '<span class="lp-pc-title" lang="' + q.lang + '" data-user-content data-testid="' + pid + '-question-title">' + esc(q.title) + '</span>' + tags(q.tags, pid + '-question', 3) + '</a>';
    var rc = '<a class="lp-pc lp-pc-r" href="pages/resource.html?id=' + r.id + '" data-testid="' + pid + '-api"><span class="lp-pc-row">' + A.thumb(r.name, { testid: pid + '-api-thumb' }) +
      '<span class="lp-pc-grow"><span class="lp-pc-name" data-testid="' + pid + '-api-name">' + esc(r.name) + '</span><span class="lp-pc-meta" data-testid="' + pid + '-api-version">' + esc(r.version) + '</span></span>' +
      statePill('verified', pid + '-api-verified', 'landing.r.verified') + '</span></a>';
    var pc = '<a class="lp-pc lp-pc-p" href="pages/project.html?id=' + p.id + '" data-testid="' + pid + '-project"><span class="lp-pc-row">' + A.thumb(p.name, { testid: pid + '-project-thumb' }) +
      '<span class="lp-pc-grow"><span class="lp-pc-name" data-testid="' + pid + '-project-name">' + esc(p.name) + '</span>' + tags(p.needs, pid + '-project', 2) + '</span>' +
      statePill('open', pid + '-project-open', 'landing.p.seeking') + '</span></a>';
    function join(icon, key, id) { return '<span class="lp-join" data-testid="' + id + '"><span class="lp-join-badge" aria-hidden="true" data-testid="' + id + '-badge">' + ic(icon, id + '-icon') + '</span>' + '<span data-testid="' + id + '-label">' + esc(t(key)) + '</span></span>'; }
    $('#lp-preview').innerHTML = '<div class="lp-stage" data-testid="' + pid + '-stage">' + qc + join('link', 'landing.preview.api', pid + '-join-api') + rc + join('hammer', 'landing.preview.project', pid + '-join-project') + pc + '</div>';
  }

  function renderQuestions() {
    $('#lp-questions').innerHTML = Q.map(function (id) {
      var x = M.byId(M.questions, id), n = 'landing-q-' + id;
      return '<li data-testid="' + n + '-item"><a class="lp-q" href="pages/question.html?id=' + id + '" data-testid="' + n + '">' +
        '<span class="lp-q-vote" data-testid="' + n + '-vote"><span class="lp-q-n tabular-nums" aria-hidden="true" data-testid="' + n + '-votes">' + x.votes + '</span><span class="lp-q-l" aria-hidden="true" data-testid="' + n + '-votes-label">' + esc(t('landing.q.votes')) + '</span><span class="visually-hidden" data-testid="' + n + '-votes-sr">' + x.votes + ' ' + esc(t('landing.q.votes')) + '</span></span>' +
        '<span class="lp-q-main"><span class="lp-q-title" lang="' + x.lang + '" data-user-content data-testid="' + n + '-title">' + esc(x.title) + '</span>' +
        '<span class="lp-q-foot">' + (x.accepted ? statePill('accepted', n + '-accepted') : '') + '<span class="lp-meta" data-testid="' + n + '-answers">' + esc(t('landing.q.answers', { n: x.answers })) + '</span>' + codes([x.country], n) + dateEl(x.date, n + '-date') + '</span>' +
        tags(x.tags, n, 3) + '</span>' + ic('chevron-right', n + '-chevron') + '</a></li>';
    }).join('');
  }

  function renderApis() {
    $('#lp-apis').innerHTML = R.map(function (id) {
      var x = M.byId(M.resources, id), n = 'landing-api-' + id, cat = M.byId(M.categories, x.category);
      return '<li class="lp-li" data-testid="' + n + '-item"><a class="lp-card" href="pages/resource.html?id=' + id + '" data-testid="' + n + '">' +
        '<span class="lp-card-head">' + A.thumb(x.name, { size: 'lg', testid: n + '-thumb' }) + '<span class="lp-card-id"><span class="lp-card-name" data-testid="' + n + '-name">' + esc(x.name) + '</span><span class="lp-meta" data-testid="' + n + '-provider">' + esc(plain(x.provider)) + '</span></span></span>' +
        '<span class="lp-card-pills">' + (x.verified ? statePill('verified', n + '-state', 'landing.r.verified') : statePill('unverified', n + '-state', 'landing.r.unverified')) + '<span class="badge" data-testid="' + n + '-category">' + esc(M.label(cat)) + '</span></span>' +
        '<span class="lp-card-text" data-testid="' + n + '-summary">' + esc(first(x.summary)) + '</span>' +
        '<span class="lp-card-foot"><span class="lp-meta lp-meta-i" data-testid="' + n + '-checked">' + ic('clock', n + '-checked-icon') + '<span data-testid="' + n + '-checked-text">' + esc(t('landing.r.checked', { d: M.fmtDate(x.verifiedAt) })) + '</span></span>' + codes(x.countries, n) + '</span></a></li>';
    }).join('');
  }

  function renderProjects() {
    $('#lp-projects').innerHTML = P.map(function (id) {
      var x = M.byId(M.projects, id), n = 'landing-project-' + id, st = PSTAT[x.status] || PSTAT.active, o = M.person(x.owner);
      return '<li class="lp-li" data-testid="' + n + '-item"><a class="lp-card" href="pages/project.html?id=' + id + '" data-testid="' + n + '">' +
        '<span class="lp-card-head">' + A.thumb(x.name, { size: 'lg', testid: n + '-thumb' }) + '<span class="lp-card-id"><span class="lp-card-name" data-testid="' + n + '-name">' + esc(x.name) + '</span><span class="lp-meta" data-testid="' + n + '-owner">' + esc(o ? o.name : '') + '</span></span></span>' +
        '<span class="lp-card-pills">' + statePill(st[0], n + '-state', st[1]) + '</span>' +
        '<span class="lp-card-text" lang="' + x.lang + '" data-user-content data-testid="' + n + '-summary">' + esc(x.summary) + '</span>' +
        '<span class="lp-card-foot"><span class="lp-needs" data-testid="' + n + '-needs">' + ic('users', n + '-needs-icon') + '<span class="visually-hidden" data-testid="' + n + '-needs-label">' + esc(t('landing.p.needs')) + '</span>' + tags(x.needs, n, 3) + '</span>' + codes([x.country], n) + '</span></a></li>';
    }).join('');
  }

  /* Signed in: the primary action becomes "Poser une question" (no sign-up pitch for someone who already has an account). */
  function syncCta() {
    var inn = A.Session.signedIn;
    [['lp-cta', 'lp-cta-label', 'landing-cta-signup'], ['lp-cta-end', 'lp-cta-end-label', 'landing-final-signup']].forEach(function (c) {
      var a = $('#' + c[0]), l = $('#' + c[1]), i = a.querySelector('.icon'); if (!a) return;
      a.setAttribute('href', A.config.signup && !inn ? 'pages/inscription.html' : A.config.ask);
      l.setAttribute('data-i18n', inn ? 'landing.cta.ask' : 'landing.cta.signup'); l.textContent = t(inn ? 'landing.cta.ask' : 'landing.cta.signup');
      i.className = 'icon ' + (inn ? 'i-plus' : 'i-user-plus');
    });
  }

  function render() { renderPreview(); renderQuestions(); renderApis(); renderProjects(); }
  function init() { document.title = t('landing.title'); render(); syncCta(); I18N.apply(); }
  document.addEventListener('DOMContentLoaded', init);
  document.addEventListener('i18n:change', function () { document.title = t('landing.title'); render(); });
  document.addEventListener('session:change', syncCta);
})();
